import { Session } from './src/session.js'

const timers={schedule(fn){queueMicrotask(fn)}}
let calls=0
const session=new Session({timers,queryFn(ctx){calls++; void ctx.signal; return new Promise(()=>{})}}, {online:false})
const h=session.subscribe('central',{networkMode:'online'})
if (session.snapshot('central').fetchStatus !== 'paused') throw new Error('initial online query was not paused')
session.unsubscribe(h)
if (session.snapshot('central').fetchStatus !== 'idle') throw new Error('orphaned paused query was not settled')
session.online(true)
await Promise.resolve()
if (calls !== 0) throw new Error(`orphaned query invoked after reconnect: ${calls}`)

let resolve
let aborts=0
const running=new Session({timers,queryFn(ctx){const signal=ctx.signal; signal.addEventListener('abort',()=>aborts++); return new Promise(r=>resolve=r)}})
const runningHandle=running.subscribe('harbor')
running.unsubscribe(runningHandle)
if (aborts !== 1 || running.snapshot('harbor').fetchStatus !== 'idle') throw new Error('signal-consuming request was not cancelled')
resolve('late')
await Promise.resolve()
if (running.snapshot('harbor').data !== null) throw new Error('late result wrote cancelled attempt')

let unconsumedResolve
const unconsumed=new Session({timers,queryFn(){return new Promise(r=>unconsumedResolve=r)}})
const unconsumedHandle=unconsumed.subscribe('museum')
unconsumed.unsubscribe(unconsumedHandle)
unconsumedResolve('cached')
await Promise.resolve()
if (unconsumed.snapshot('museum').data !== 'cached') throw new Error('unconsumed request did not populate cache')
console.log('session checks passed')
